input.command:
cd /work/workspace/deliverable && python3 -c "
import json
d=json.load(open('q1_close.json'))
assert set(d['months'])=={'01','02','03'}
q1={k:round(sum(d['months'][m][k] for m in d['months']),2) for k in ('revenue','payroll','supplies','rent')}
q1['other']={k:round(sum(d['months'][m]['other'][k] for m in d['months']),2) for k in d['months']['01']['other']}
print('JSON valid. Q1 totals:',q1)
print('crossfoot rev-debits:', round(q1['revenue']-(q1['payroll']+q1['supplies']+q1['rent']+sum(q1['other'].values())),2))" && wc -l *.md && ls

